 add({id:'python-print-message',title:'Luyện print(): thông báo ngắn',goal:'Luyện dùng print() để in một câu khác.',use:'Dùng để in chữ ra màn hình, như một câu chào hoặc lời nhắn.',knowledge:'<p>Ôn lại: <code>print("nội dung")</code> hiển thị chuỗi trong dấu nháy. Muốn in câu khác, đổi phần chữ trong dấu nháy. Giữ nguyên print và cặp ngoặc.</p><p>Dấu nháy đơn và kép đều dùng được nếu mở và đóng cùng loại. Khoảng trắng bên trong chuỗi được giữ khi hiển thị.</p>',example:'print("Chào buổi sáng")',explanation:'Dòng này in ra Chào buổi sáng. Để làm bài, bạn thay câu trong dấu nháy bằng câu đề bài yêu cầu.',exampleOutput:'Chào buổi sáng',task:'Hiển thị đúng một dòng: Kết nối dữ liệu thành công',expected:'Kết nối dữ liệu thành công',hints:['Dùng lại print() như bài trước.','Thông báo cần đặt bên trong dấu nháy.','Đối chiếu chữ, dấu và khoảng trắng với output mong đợi.'],solution:'print("Kết nối dữ liệu thành công")'});
 add({id:'python-print-lines',title:'Luyện print(): nhiều dòng theo thứ tự',goal:'Dùng lại nhiều lệnh print() để hiển thị các dòng đúng thứ tự.',use:'Dùng để in nhiều dòng chữ, giống viết mỗi món trong danh sách trên một dòng.',knowledge:'<p>Python chạy các lệnh này từ trên xuống. Mỗi lệnh <code>print()</code> in xong sẽ xuống dòng.</p><p>Muốn in nhiều dòng, viết thêm các lệnh print giống lệnh bạn đã biết.</p>',example:'print("Bánh mì")\nprint("Sữa")',explanation:'Lệnh đầu in Bánh mì, lệnh sau in Sữa ở dòng tiếp theo. Đổi thứ tự hai lệnh thì hai dòng cũng đổi chỗ.',exampleOutput:'Bánh mì\nSữa',task:'Hiển thị ba dòng theo đúng thứ tự: SQL, Python, API. Mỗi tên nằm trên một dòng riêng',expected:'SQL\nPython\nAPI',hints:['Mỗi lệnh print() có thể hiển thị một dòng.','Viết các tên theo đúng thứ tự từ trên xuống.','Output cần ba dòng, không có dấu phẩy hoặc dòng trống xen giữa.'],solution:'print("SQL")\nprint("Python")\nprint("API")'});
 add({id:'python-variable-name',title:'Biến: lưu và hiển thị tên',goal:'Biết lưu một tên vào biến rồi in tên đó ra.',use:'Dùng để giữ một thông tin, chẳng hạn tên của bạn, rồi lấy ra dùng lại.',knowledge:'<p><strong>Biến — variable</strong> là một tên dùng để giữ giá trị. Ví dụ <code>name = "Minh"</code> nghĩa là biến name giữ chữ Minh. Dấu <code>=</code> dùng để gán giá trị cho biến.</p><p><code>print(name)</code> đọc giá trị của biến; <code>print("name")</code> chỉ hiển thị chữ name. Gán giá trị trước rồi mới dùng biến. Python phân biệt chữ hoa và chữ thường.</p>',example:'name = "Minh"\nprint(name)',explanation:'Dòng đầu gán chuỗi Minh cho biến name. Dòng thứ hai đọc biến đó và hiển thị Minh; vì vậy name trong print không đặt trong dấu nháy.',exampleOutput:'Minh',task:'Gán chuỗi Lan cho biến name, rồi dùng print() hiển thị giá trị của biến name',expected:'Lan',variable:'name',hints:['Gán văn bản cho biến bằng dấu = trước khi hiển thị.','Giá trị Lan cần dấu nháy; tên biến name không cần dấu nháy.','Trong print(), dùng tên biến để đọc giá trị đã gán, không in trực tiếp chuỗi Lan.'],solution:'name = "Lan"\nprint(name)'});
 add({id:'python-variable-status',title:'Luyện biến: trạng thái xử lý',goal:'Luyện lưu một trạng thái vào biến rồi in ra.',use:'Dùng để giữ một trạng thái, ví dụ Đang học hoặc Đang nghỉ.',knowledge:'<p><code>status</code> nghĩa là trạng thái. Đây chỉ là tên biến, giống name ở bài trước. Bạn vẫn gán chữ cho biến bằng dấu <code>=</code>.</p><p>Gán giá trị trước, rồi dùng <code>print(status)</code> để in giá trị đó ra. Đặt tên biến trong dấu nháy sẽ chỉ in ra chữ status.</p>',example:'status = "Đang học"\nprint(status)',explanation:'Dòng đầu lưu Đang học vào biến status. Dòng sau in giá trị của status ra màn hình.',exampleOutput:'Đang học',task:'Gán chuỗi Đã kết nối cho biến status, rồi dùng print() hiển thị giá trị của biến status',expected:'Đã kết nối',variable:'status',hints:['Dùng status làm tên biến, tương tự name ở bài trước.','Gán chuỗi trạng thái đúng như đề trước khi gọi print.','Dùng print(status) để đọc biến, thay vì in chữ status trong dấu nháy.'],solution:'status = "Đã kết nối"\nprint(status)'});
 add({id:'python-variable-topic',title:'Luyện biến: chủ đề đang học',goal:'Luyện lưu tên chủ đề đang học vào biến rồi in ra.',use:'Dùng để nhớ bạn đang học gì, chẳng hạn Toán hoặc Python.',knowledge:'<p><code>topic</code> nghĩa là chủ đề. Cách dùng giống name và status: gán chữ cho biến rồi dùng print để in ra.</p><p>Ở dòng gán, phần chữ cần giữ nằm trong dấu nháy. Ở dòng print, tên biến không nằm trong dấu nháy.</p>',example:'topic = "Toán"\nprint(topic)',explanation:'Dòng đầu lưu Toán vào biến topic. Dòng sau in Toán ra. Muốn đổi chủ đề, bạn đổi chữ ở dòng gán.',exampleOutput:'Toán',task:'Gán chuỗi Python cho biến topic, rồi dùng print() hiển thị giá trị của biến topic',expected:'Python',variable:'topic',hints:['Bài này dùng lại đúng hai bước: gán rồi hiển thị.','Tên biến cần dùng là topic; giá trị cần lưu là chuỗi Python.','Đối chiếu tên biến ở dòng gán và dòng print; hai tên phải giống nhau.'],solution:'topic = "Python"\nprint(topic)'});
